def test_unicode(self):
    """
    Test Unicode handling.
    """
    release = ghstats.download_stats("d3", "d3", "v3.5.0", False, ghstats.get_env_token(), False)
    try:
        ghstats.get_release_downloads(release)
    except UnicodeEncodeError:
        self.fail("Could not handle Unicode release statistics.")

def test_threaded(self):
    threads = [threading.Thread(target=self.profile_a_busy_wait) for _ in range(10)]
    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    # threaded counts can be way lower, presumably due to the GIL.
    # Really we only care that it didn't crash!
    self.assertTrue(50 < self.count < 125,
            'profile count should be approx. 100, was %i' % self.count)

def test_httpy_get_status_codes(capsys):
    httpy.set_debug(False)
    with capsys.disabled():
        iterator=httpy.STATUS_CODES
        if alive_progress:
            iterator=alive_progress.alive_it(iterator)
        print()
        for code in iterator:
            if 400<=int(code):
                assert httpy.request(f'https://httpbin.org/status/{code}',enable_cache=False).status==int(code)

@pytest.mark.skipif(not _connected(), reason = 'no connection to internet')
def test_post_io():
    ret = json.loads(webPortal.post('https://httpbin.org/post', params = {'b': 'bb'}, headers = {'a': 'aa'}))
    assert ret['args'] == {'b': 'bb'}
    assert ret['headers']['A'] == 'aa' and ret['headers']['Host'] == 'httpbin.org'
    assert ret['url'] == 'https://httpbin.org/post?b=bb'

    ret = webPortal.post('https://httpbin.org/no-such-website', tries = 3)
    assert missing(ret)

    ret = webPortal.post('http://no-such-website.com', tries = 3)
    assert missing(ret)

@staticmethod
def test_closed_issue_check_does_not_fail_when_closed(
    assert_github_issue_no_cache: AssertGitHubIssue,
):
    assert_github_issue_no_cache.is_closed(CLOSED_ISSUE_NUMBER)

@staticmethod
def test_closed_issue_check_fails_when_open(
    assert_github_issue_no_cache: AssertGitHubIssue,
):
    with pytest.raises(AssertionError):
        assert_github_issue_no_cache.is_closed(OPEN_ISSUE_NUMBER)

@staticmethod
def test_open_issue_check_does_not_fail_when_open(
    assert_github_issue_no_cache: AssertGitHubIssue,
):
    assert_github_issue_no_cache.is_open(OPEN_ISSUE_NUMBER)

@staticmethod
def test_open_issue_check_fails_when_closed(
    assert_github_issue_no_cache: AssertGitHubIssue,
):
    with pytest.raises(AssertionError):
        try:
            assert_github_issue_no_cache.is_open(CLOSED_ISSUE_NUMBER, "Custom message.")
        except AssertionError as ex:
            print(ex)
            raise ex

@staticmethod
def test_release_number_check_fails_when_new_releases_available(
    assert_github_issue_no_cache: AssertGitHubIssue,
):
    with pytest.raises(AssertionError, match=".*New release of .*") as ex:
        assert_github_issue_no_cache.current_release(0)

    print(ex)  # for quick grab of string for documentation

def test_hmc_sampling(self, rhvae_sample, rhvae_sampler_config):

    # simulates a trained model
    # rhvae_sample.centroids_tens = torch.randn(20, rhvae_sample.latent_dim)
    # rhvae_sample.M_tens = torch.randn(20, rhvae_sample.latent_dim, rhvae_sample.latent_dim)

    sampler = RHVAESampler(model=rhvae_sample, sampler_config=rhvae_sampler_config)

    out = sampler.hmc_sampling(rhvae_sampler_config.batch_size)

    assert out.shape == (rhvae_sampler_config.batch_size, rhvae_sample.latent_dim)

    assert sampler.eps_lf == rhvae_sampler_config.eps_lf

    assert all(
        [
            not torch.equal(out[i], out[j])
            for i in range(len(out))
            for j in range(i + 1, len(out))
        ]
    )

